---@class ActivityMournDojo
local ActivityMournDojo = Class("ActivityMournDojo")

function ActivityMournDojo:__init()
    ---@type table 活动配置信息
    self.activityConf = {}
    ---@type table 剧情通关信息
    self.plotInfo = {}
	
	self.clearanceRewards = 0
	
	self.closeTime = 0
	
	self.endTime = 0
	
	self.isBossUnlock = 0
	
	self.nextHpSeconds = 0
	
	self.nowQuestId = 0
	
	self.recoverSeconds = 0
	
	self.startTime = 0
	
	---@type table 使用道具解锁的关卡 0未解锁  1已解锁
	self.unlockPlotInfo = {}
	
	self.unlockChapterInfo = {}
	
	self.climbingInfo = {}
	
	self.climbingResetNum = 0
	
	self.limit = 0
	
	self.climbingResetTtl = 0
	
	self._climbingHaveBuffIds = {}              --已解锁的道具 key goodsId value level
	
	self._redPointList = {}
	
	self.upGroup = {}
	
	self._timeDown = nil
	
	self._isInit = false
end

---FillVo
---@param row TableML.TableFileRow
function ActivityMournDojo:Fill(jsonData)
	jsonData = checkTable(jsonData)
	local curTime = GameUtils.GetServerTime() or os.time()
	for key, value in pairs(jsonData) do
		--只更新自己关心的数据
		if isSet(jsonData, key) and table.haskey(self, key) then
			if key == "unlockChapterInfo" then
				for i, v in pairs(value) do
					if checkNumber(v.unlockCountdown) > 0 then
						v.unlockCountdown = v.unlockCountdown + curTime
					end
				end
			end
			self[key] = value
		end
	end
	
	if isSet(jsonData,"closeTime") then
		self.closeTime = self.closeTime + curTime
	end
	
	if isSet(jsonData,"nextHpSeconds") then
		self.nextHpSeconds = self.nextHpSeconds + curTime
	end
	
	if isSet(jsonData,"endTime") then
		self.endTime = self.endTime + curTime
	end
	
	if self._isInit then
		local t1 = checkTable(self.climbingInfo.climbingHaveBuffIds)
		local t2 = checkTable(self._climbingHaveBuffIds)
		
		for k, v in pairs(t1) do
			if checkNumber(t2[checkString(k)]) == 0 then
				self._redPointList[checkString(k)] = 1
			end
		end
		
		self._climbingHaveBuffIds = checkTable(self.climbingInfo.climbingHaveBuffIds)
	else
		if isNull(self._redPointList) then
			self._redPointList = {}
		end
		
		self._climbingHaveBuffIds = checkTable(self.climbingInfo.climbingHaveBuffIds)
		self._isInit = true
	end
end

function ActivityMournDojo:GetCurTowerId()
	return self.climbingInfo.climbingNowFloor
end

function ActivityMournDojo:GetChapterInfo()
	return self.unlockChapterInfo
end

function ActivityMournDojo:IsUseItemLockPlot(plotId)
	if self.unlockPlotInfo[tostring(plotId)] then
		return self.unlockPlotInfo[tostring(plotId)] == 1
	end
	return false
end

function ActivityMournDojo:UpdateItemLockPlot(id)
	id = checkString(id)
	if self.unlockPlotInfo[id] then
		self.unlockPlotInfo[id] = 1
	end
	self.unlockPlotInfo[id] = 1
end

function ActivityMournDojo:IsBossUnLock()
	return checkNumber(self.isBossUnlock) == 1
end

function ActivityMournDojo:UpdateCurTowerId(id)
	self.climbingInfo.climbingNowFloor = id
end

function ActivityMournDojo:GetMaxPassTowerId()
	return self.climbingInfo.climbingMaxFloor
end

function ActivityMournDojo:RemoveBuffList(buffId)
	buffId = checkString(buffId)
	if isNotNull(self._redPointList[buffId]) then
		self._redPointList[buffId] = 0
	end
end

function ActivityMournDojo:UpdateMaxFloorId(questId)
	if questId > checkNumber(self.climbingInfo.climbingMaxFloor) then
		self.climbingInfo.climbingMaxFloor = questId
	end
end

function ActivityMournDojo:GetEquipBuffIds()
	return self.climbingInfo.climbingAssembleBuffIds
end

function ActivityMournDojo:UpdateAssembleBuffIds(assembleBuffIds)
	self.climbingInfo.climbingAssembleBuffIds = assembleBuffIds
end

function ActivityMournDojo:GetNowQuestId()
	return self.nowQuestId
end

function ActivityMournDojo:UpdateNowQuestId(questId)
	questId = checkNumber(questId)
	if questId > self.nowQuestId then
		self.nowQuestId = questId
	end
end

function ActivityMournDojo:GetUpGroup()
	return self.upGroup
end

function ActivityMournDojo:RuleId()
	return self.activityConf.ruleId
end

function ActivityMournDojo:GetSchConfig()
	return self.activityConf
end

function ActivityMournDojo:GetShowCurrency()
	return self.activityConf.token
end

function ActivityMournDojo:IsUnLockBuff(buffId)
	return checkNumber(self._climbingHaveBuffIds[checkString(buffId)]) > 0
end

function ActivityMournDojo:UpdateHaveBuffLevels(buffId, level)
	if self._climbingHaveBuffIds[checkString(buffId)] then
		self._climbingHaveBuffIds[checkString(buffId)] = level
	end
end

function ActivityMournDojo:IsEquipBuff(buffId)
	if not self.climbingInfo.climbingAssembleBuffIds then
		return false
	end
	local ind = table.keyof(self.climbingInfo.climbingAssembleBuffIds, checkNumber(buffId))
	
	return checkNumber(ind) > 0
end

function ActivityMournDojo:IsBuffMaxLevel(buffId)
	if not self._climbingHaveBuffIds then
		return false
	end
	
	local goodsVo = CfUtils.GetCfVo(AutoIds.IdSetting6609, "NightCatGoodsVo", buffId)
	local level = self._climbingHaveBuffIds[checkString(buffId)]
	
	return checkNumber(level) >= checkNumber(goodsVo.maxLevel)
end

function ActivityMournDojo:GetBuffLevel(buffId)
	if not self._climbingHaveBuffIds then
		return false
	end
	local level = self._climbingHaveBuffIds[checkString(buffId)]
	return checkNumber(level)
end

function ActivityMournDojo:IsBuffNew(buffId)
	if not self._redPointList then
		return false
	end
	return (checkNumber(self._redPointList[checkString(buffId)]) == 1)
end

function ActivityMournDojo:UpdateRedPointList(data)
	self._redPointList = data
end

function ActivityMournDojo:RefreshResetInfo(jsonData)
	self.climbingResetNum = checkNumber(jsonData.climbingResetNum)
	self.limit = checkNumber(jsonData.limit)
	local curTime = GameUtils.GetServerTime() or os.time()
	self.nextHpSeconds = checkNumber(jsonData.nextHpSeconds) + curTime
	self.recoverSeconds = checkNumber(jsonData.recoverSeconds)
end

function ActivityMournDojo:__delete()

end

return ActivityMournDojo